import React from 'react';
import { Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ComposedChart, Line, ReferenceLine } from 'recharts';
import {PointDTO} from "../../types";

interface Props {
    points: PointDTO[];
    a: number;
    b: number;
}const IntegrationChart = ({ points, a, b }: Props) => {
    // 1. Защита от null (та самая ошибка map)
    if (!points || !Array.isArray(points)) return null;

    // 2. Упрощение: если точек > 1000, берем каждую N-ю
    const simplifiedData = useMemo(() => {
        const MAX_POINTS = 1000;
        if (points.length <= MAX_POINTS) return points;

        const step = Math.ceil(points.length / MAX_POINTS);
        return points.filter((_, index) => index % step === 0);
    }, [points]);

    return (
        <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
                {/* Используем simplifiedData вместо points */}
                <ComposedChart data={simplifiedData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="x" type="number" domain={[a, b]} hide />
                    <YAxis hide />
                    <Tooltip
                        labelFormatter={(v) => `x: ${Number(v).toFixed(3)}`}
                        formatter={(v: any) => [Number(v).toFixed(4), "y"]}
                    />
                    {/* Рисуем область (интеграл) */}
                    <Area type="monotone" dataKey="y" fill="#6366f1" fillOpacity={0.1} stroke="none" />
                    {/* Рисуем линию функции */}
                    <Line type="monotone" dataKey="y" stroke="#4f46e5" dot={false} strokeWidth={2} />
                </ComposedChart>
            </ResponsiveContainer>
        </div>
    );
};

export default IntegrationChart;
